export function createPointRouteFetchHandler() {
  return async (req) => {
    const url = new URL(req.url);
  if (req.method === "GET" && new RegExp("^\\/items$").test(url.pathname)) {
    const match = url.pathname.match(new RegExp("^\\/items$"));
    const queryRecord = pointQueryRecord(url.searchParams, ["limit"]);
    const headerRecord = pointHeaderRecord(req.headers, ["authorization"]);
    {
      const middlewareResult = requireAuthMiddleware(headerRecord);
      if (middlewareResult != null) return pointRouteResponse(middlewareResult, { status: 401 });
    }
    {
      const middlewareResult = auditRequestMiddleware(headerRecord);
      if (middlewareResult != null) return pointRouteResponse(middlewareResult, { status: 401 });
    }
    const handlerResult = getItemRoute(headerRecord, queryRecord);
    return pointRouteResponse(await handlerResult);
  }
  if (req.method === "POST" && new RegExp("^\\/items$").test(url.pathname)) {
    const match = url.pathname.match(new RegExp("^\\/items$"));
    const headerRecord = pointHeaderRecord(req.headers, ["authorization"]);
    const bodyRecord = await pointBodyRecord(req, ["name"]);
    {
      const middlewareResult = requireAuthMiddleware(headerRecord);
      if (middlewareResult != null) return pointRouteResponse(middlewareResult, { status: 401 });
    }
    const handlerResult = createItemRoute(headerRecord, bodyRecord);
    return pointRouteResponse(await handlerResult);
  }
    return new Response(JSON.stringify({ error: "Not found" }), { status: 404, headers: { "content-type": "application/json" } });
  };
}

